#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define NSEED (1u << 20)
#define NPAIRS 32
#define SIGPAIRS 4   /* number of pairs used in the MITM signature */

static uint32_t rotl2(uint32_t t) { return ((t << 2) | (t >> 6)) & 0xFF; }

static uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    return (uint8_t)(((a + b + x) & 0xFF) << 2 | ((a + b + x) & 0xFF) >> 6);
}

static uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1] ^ x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);
    uint32_t out = 0;
    for (int i = 0; i < 4; i++) out |= (uint32_t)y[i] << (8 * i);
    return out;
}

/* Inverse of f_function, verified numerically. */
static uint32_t f_inv(uint32_t v) {
    uint8_t a[4], x[4];
    for (int i = 0; i < 4; i++) { a[i] = v & 0xFF; v >>= 8; }
    uint8_t r0 = (uint8_t)((a[0] >> 2) | (a[0] << 6));
    uint8_t r1 = (uint8_t)((a[1] >> 2) | (a[1] << 6));
    uint8_t r2 = (uint8_t)((a[2] >> 2) | (a[2] << 6));
    uint8_t r3 = (uint8_t)((a[3] >> 2) | (a[3] << 6));
    x[0] = (uint8_t)(r0 - a[1] - 1);
    uint8_t p = (uint8_t)(r1 - a[2]);
    x[3] = (uint8_t)(r3 - a[2]);
    uint8_t q = (uint8_t)(r2 - p - 1);
    x[2] = x[3] ^ q;
    x[1] = p ^ x[0];
    return (uint32_t)x[0] | ((uint32_t)x[1] << 8) |
           ((uint32_t)x[2] << 16) | ((uint32_t)x[3] << 24);
}

static uint32_t expand(uint32_t k) {
    k &= 0xFFFFF;
    return k ^ (k << 16) ^ (k * 12345u);
}

static uint64_t enc(uint64_t pt, const uint32_t *key) {
    uint32_t left = (uint32_t)(pt >> 32);
    uint32_t right = (uint32_t)pt;
    right ^= left;
    for (int r = 0; r < 4; r++) {
        uint32_t mixed = f_function(right ^ key[r]);
        uint32_t temp = right;
        right = left ^ mixed;
        left = temp;
    }
    left ^= right;
    return ((uint64_t)right << 32) | left;
}

typedef struct {
    uint32_t s0, s1, s2;
    uint32_t key;
    uint32_t aux;   /* phi0 for left table, psi0 for right table */
} entry_t;

static int cmp_entry(const void *A, const void *B) {
    const entry_t *a = A, *b = B;
    if (a->s0 != b->s0) return a->s0 < b->s0 ? -1 : 1;
    if (a->s1 != b->s1) return a->s1 < b->s1 ? -1 : 1;
    if (a->s2 != b->s2) return a->s2 < b->s2 ? -1 : 1;
    return 0;
}

static int cmp_u32(const void *A, const void *B) {
    uint32_t a = *(const uint32_t *)A, b = *(const uint32_t *)B;
    return a < b ? -1 : (a > b ? 1 : 0);
}

static int key_in_set(uint32_t k, const uint32_t *sorted, uint32_t n) {
    return bsearch(&k, sorted, n, sizeof(uint32_t), cmp_u32) != NULL;
}

int main(int argc, char **argv) {
    const char *pairs_path = argc > 1 ? argv[1] : "pairs.txt";
    const char *ct_path    = argc > 2 ? argv[2] : "ciphertexts.txt";
    const char *out_path   = argc > 3 ? argv[3] : "plaintexts.txt";

    uint32_t Lp[NPAIRS], Rp[NPAIRS], R0[NPAIRS], R3[NPAIRS], R4[NPAIRS];
    uint64_t pts[NPAIRS], cts[NPAIRS];

    FILE *fp = fopen(pairs_path, "r");
    if (!fp) { perror("pairs.txt"); return 1; }
    int np = 0;
    unsigned long long a, b;
    while (np < NPAIRS && fscanf(fp, "%llu %llu", &a, &b) == 2) {
        uint64_t p = (uint64_t)a, c = (uint64_t)b;
        pts[np] = p; cts[np] = c;
        Lp[np] = (uint32_t)(p >> 32);
        Rp[np] = (uint32_t)p;
        R0[np] = Rp[np] ^ Lp[np];
        uint32_t chi = (uint32_t)(c >> 32);
        uint32_t clo = (uint32_t)c;
        R4[np] = chi;
        R3[np] = chi ^ clo;
        np++;
    }
    fclose(fp);
    if (np != NPAIRS) { fprintf(stderr, "expected %d pairs, got %d\n", NPAIRS, np); return 1; }
    fprintf(stderr, "loaded %d pairs\n", np);

    /* Membership set: all expanded round-key values reachable from a 20-bit seed. */
    uint32_t *keyvals = malloc(sizeof(uint32_t) * NSEED);
    uint32_t *seeds_for = malloc(sizeof(uint32_t) * NSEED);
    if (!keyvals || !seeds_for) { fprintf(stderr, "oom\n"); return 1; }
    for (uint32_t s = 0; s < NSEED; s++) {
        keyvals[s] = expand(s);
        seeds_for[s] = s;
    }
    uint32_t *sorted_keys = malloc(sizeof(uint32_t) * NSEED);
    memcpy(sorted_keys, keyvals, sizeof(uint32_t) * NSEED);
    qsort(sorted_keys, NSEED, sizeof(uint32_t), cmp_u32);
    uint32_t nuniq = 0;
    for (uint32_t i = 0; i < NSEED; i++)
        if (i == 0 || sorted_keys[i] != sorted_keys[nuniq - 1])
            sorted_keys[nuniq++] = sorted_keys[i];
    fprintf(stderr, "distinct expanded keys: %u (of %u seeds)\n", nuniq, NSEED);

    entry_t *left = malloc(sizeof(entry_t) * NSEED);
    entry_t *right = malloc(sizeof(entry_t) * NSEED);
    if (!left || !right) { fprintf(stderr, "oom\n"); return 1; }

    /* Left: K0 guesses, forward rounds 0/1 -> phi_i = R1_i */
    for (uint32_t s = 0; s < NSEED; s++) {
        uint32_t k0 = keyvals[s];
        uint32_t phi0 = 0, phi[SIGPAIRS];
        for (int i = 0; i < SIGPAIRS; i++) {
            phi[i] = Lp[i] ^ f_function(R0[i] ^ k0);
            if (i == 0) phi0 = phi[i];
        }
        left[s].s0 = phi[1] ^ phi[0];
        left[s].s1 = phi[2] ^ phi[0];
        left[s].s2 = phi[3] ^ phi[0];
        left[s].key = k0;
        left[s].aux = phi0;
    }
    fprintf(stderr, "left table built\n");

    /* Right: K3 guesses, backward round 3 -> psi_i = Finv(R2_i ^ R0_i) */
    for (uint32_t s = 0; s < NSEED; s++) {
        uint32_t k3 = keyvals[s];
        uint32_t psi0 = 0, psi[SIGPAIRS];
        for (int i = 0; i < SIGPAIRS; i++) {
            uint32_t r2 = R4[i] ^ f_function(R3[i] ^ k3);
            psi[i] = f_inv(r2 ^ R0[i]);
            if (i == 0) psi0 = psi[i];
        }
        right[s].s0 = psi[1] ^ psi[0];
        right[s].s1 = psi[2] ^ psi[0];
        right[s].s2 = psi[3] ^ psi[0];
        right[s].key = k3;
        right[s].aux = psi0;
    }
    fprintf(stderr, "right table built\n");

    qsort(left, NSEED, sizeof(entry_t), cmp_entry);
    qsort(right, NSEED, sizeof(entry_t), cmp_entry);
    fprintf(stderr, "tables sorted\n");

    uint32_t found_keys[4];
    int found = 0;
    uint32_t cand = 0;

    for (uint32_t i = 0, j = 0; i < NSEED && j < NSEED; ) {
        int c = cmp_entry(&left[i], &right[j]);
        if (c < 0) { i++; continue; }
        if (c > 0) { j++; continue; }
        uint32_t ie = i, je = j;
        while (ie < NSEED && left[ie].s0 == left[i].s0 && left[ie].s1 == left[i].s1 && left[ie].s2 == left[i].s2) ie++;
        while (je < NSEED && right[je].s0 == right[i].s0 && right[je].s1 == right[i].s1 && right[je].s2 == right[i].s2) je++;
        for (uint32_t li = i; li < ie; li++) {
            for (uint32_t rj = j; rj < je; rj++) {
                uint32_t k0 = left[li].key, k3 = right[rj].key;
                uint32_t k1 = left[li].aux ^ right[rj].aux;
                if (!key_in_set(k1, sorted_keys, nuniq)) continue;
                cand++;
                /* Derive K2 from round 2 and require consistency + reachability. */
                uint32_t k2 = 0; int ok = 1;
                for (int p = 0; p < NPAIRS; p++) {
                    uint32_t r1 = Lp[p] ^ f_function(R0[p] ^ k0);
                    uint32_t r2 = R4[p] ^ f_function(R3[p] ^ k3);
                    uint32_t k2p = r2 ^ f_inv(r1 ^ R3[p]);
                    if (p == 0) k2 = k2p;
                    else if (k2p != k2) { ok = 0; break; }
                }
                if (!ok) continue;
                if (!key_in_set(k2, sorted_keys, nuniq)) continue;
                uint32_t keys[4] = { k0, k1, k2, k3 };
                int all = 1;
                for (int p = 0; p < NPAIRS; p++)
                    if (enc(pts[p], keys) != cts[p]) { all = 0; break; }
                if (all) {
                    found = 1;
                    memcpy(found_keys, keys, sizeof(keys));
                    fprintf(stderr, "CANDIDATE MATCH: k0=%08X k1=%08X k2=%08X k3=%08X\n",
                            k0, k1, k2, k3);
                }
            }
        }
        i = ie; j = je;
    }

    if (!found) { fprintf(stderr, "no key found (candidates tested: %u)\n", cand); return 1; }

    /* Recover a 20-bit seed for each expanded round key. */
    uint32_t seeds[4];
    for (int r = 0; r < 4; r++) {
        seeds[r] = 0xFFFFFFFFu;
        for (uint32_t s = 0; s < NSEED; s++) {
            if (expand(s) == found_keys[r]) { seeds[r] = s; break; }
        }
        if (seeds[r] == 0xFFFFFFFFu) { fprintf(stderr, "no seed for key %d\n", r); return 1; }
    }
    printf("Recovered round keys: ");
    for (int r = 0; r < 4; r++) printf("%08X%c", found_keys[r], r == 3 ? '\n' : ' ');
    printf("Recovered seeds:      ");
    for (int r = 0; r < 4; r++) printf("0x%05X%c", seeds[r], r == 3 ? '\n' : ' ');
    fflush(stdout);

    /* Decrypt every ciphertext (same logic as decrypt.c) and save decimal plaintexts. */
    FILE *cf = fopen(ct_path, "r");
    if (!cf) { perror(ct_path); return 1; }
    FILE *of = fopen(out_path, "w");
    if (!of) { perror(out_path); return 1; }
    unsigned long long ct;
    size_t count = 0;
    while (fscanf(cf, "%llu", &ct) == 1) {
        uint32_t left = (uint32_t)ct;           /* getright */
        uint32_t right = (uint32_t)(ct >> 32);  /* getleft */
        left ^= right;
        for (int r = 3; r >= 0; r--) {
            uint32_t temp = left;
            left = right;
            uint32_t mixed = f_function(temp ^ found_keys[r]);
            right = temp;
            left ^= mixed;
        }
        right ^= left;
        uint64_t pt = ((uint64_t)left << 32) | right;
        fprintf(of, "%llu\n", (unsigned long long)pt);
        count++;
    }
    fclose(cf);
    fclose(of);
    fprintf(stderr, "wrote %zu plaintexts to %s\n", count, out_path);
    return 0;
}

